    if 5 <= r <= 10 or 6 <= c <= 11 or (5-1 <= r <= 10+1 and 6-1 <= c <= 11+1):
        neighbors_with_numbers = []
        for nr, nc, val in [(r+1,c), (r-1,c), (r,c+1), (r,c-1), (r+1,c+1), (r+1,c-1), (r-1,c+1), (r-1,c-1)]:
